// Các regimen chưa được BV199 phê duyệt. Không sao chép vào y lệnh tự động.
const addVerified=(needle:string, regs:Reg[],checks:string[])=>{
 const hit=topics.find(t=>t.title===needle);
 if(hit){hit.regimens.push(...regs);hit.checks=checks;hit.context='Dữ liệu nguồn quốc tế tham khảo; cần đánh giá người bệnh và đối chiếu quy trình BV199.';}
};
